import sys
from collections import deque

def countOfNodes(graph, n):
    if n == 0:
        return 0

    visited = [False] * n
    color = [-1] * n
    count0 = 0
    count1 = 0

    def bfs(start):
        nonlocal count0, count1
        queue = deque([start])
        visited[start] = True
        color[start] = 0
        count0 += 1

        while queue:
            u = queue.popleft()
            current_color = color[u]
            next_color = 1 - current_color

            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    color[v] = next_color
                    if next_color == 0:
                        count0 += 1
                    else:
                        count1 += 1
                    queue.append(v)

    for i in range(1, n + 1):
        if not visited[i]:
            count0 = 0
            count1 = 0
            bfs(i)
            break

    return count0 * (count0 - 1) // 2 + count1 * (count1 - 1) // 2

def main():
    try:
        line = sys.stdin.readline().strip()
        if not line:
            return
        n = int(line)

        graph_input = []
        for _ in range(n):
            row = sys.stdin.readline().strip()
            if row:
                parts = row.split(',')
                nums = [int(x.strip()) for x in parts if x.strip()]
                graph_input.append(nums)
            else:
                graph_input.append([])

        adj = [[] for _ in range(n + 1)]
        for i in range(n):
            node_idx = i + 1
            for neighbor in graph_input[i]:
                adj[node_idx].append(neighbor)

        result = countOfNodes(adj, n)
        print(result)
    except Exception:
        pass

if __name__ == "__main__":
    main()
